typedef enum {                                  /*!< SECURETIMER_CTRL3_TMR3FN                                                  */
  SECURETIMER_CTRL3_TMR3FN_EDGE        = 1,     /*!< EDGE : This Mode generates a single edge on OUT0/OUT1 when TIMER
                                                     value hits CMP0/CMP1 respectively. OUT[0]=0, counter increments
                                                     to CMP0, OUT[0]=1, counter stops. OUT[1] follows CMP1.                    */
  SECURETIMER_CTRL3_TMR3FN_UPCOUNT     = 2,     /*!< UPCOUNT : This mode is run up counter generating a pulse on
                                                     CMP. OUT[0]/OUT[1] is pulsed for one source clock period
                                                     when TIMER matches CMP0/CMP1 respectively. Timer repeats
                                                     for TMR_LMT iterations.                                                   */
  SECURETIMER_CTRL3_TMR3FN_PWM         = 4,     /*!< PWM : PWM mode. OUT0 and OUT1 are waveforms, and not just one
                                                     clock pulse. CMP1 dictates the low phase of the output
                                                     and CMP0 dictates the period. OUT[1]=~OUT[0].                             */
  SECURETIMER_CTRL3_TMR3FN_SINGLEPATTERN = 12,  /*!< SINGLEPATTERN : Single pattern. OUT0=CMP0[TIMER], OUT1=CMP1[TIMER].
                                                     LMT field specifies length of pattern. When LMT is greater
                                                     than or equal to 32, OUT0 and OUT1 use the same 64-bit
                                                     pattern consisting of concatenated CMP1, CMP0. When LMT
                                                     is less than 32, OUT0 and OUT1 are independent. Both OUT0
                                                     and OUT1 can be inverted individually applications with
                                                     POL0/POL1 = 0x1.                                                          */
  SECURETIMER_CTRL3_TMR3FN_REPEATPATTERN = 13,  /*!< REPEATPATTERN : Repeated pattern. Like SINGLEPATTERN mode, but
                                                     pattern repeats after reaching LMT.                                       */
} SECURETIMER_CTRL3_TMR3FN_Enum;

/* ===========================================  SECURETIMER CTRL3 TMR3POL1 [3..3]  =========================================== */
typedef enum {                                  /*!< SECURETIMER_CTRL3_TMR3POL1                                                */
  SECURETIMER_CTRL3_TMR3POL1_NORMAL    = 0,     /*!< NORMAL : The polarity of the TMR3OUT1 pin is the same as the
                                                     timer output.                                                             */
  SECURETIMER_CTRL3_TMR3POL1_INVERTED  = 1,     /*!< INVERTED : The polarity of the TMR3OUT1 pin is the inverse of
                                                     the timer output.                                                         */
} SECURETIMER_CTRL3_TMR3POL1_Enum;

/* ===========================================  SECURETIMER CTRL3 TMR3POL0 [2..2]  =========================================== */
typedef enum {                                  /*!< SECURETIMER_CTRL3_TMR3POL0                                                */
  SECURETIMER_CTRL3_TMR3POL0_NORMAL    = 0,     /*!< NORMAL : The polarity of the TMR3OUT0 pin is the same as the
                                                     timer output.                                                             */
  SECURETIMER_CTRL3_TMR3POL0_INVERTED  = 1,     /*!< INVERTED : The polarity of the TMR3OUT0 pin is the inverse of
                                                     the timer output.                                                         */
} SECURETIMER_CTRL3_TMR3POL0_Enum;

/* ===========================================  SECURETIMER CTRL3 TMR3CLR [1..1]  ============================================ */
typedef enum {                                  /*!< SECURETIMER_CTRL3_TMR3CLR                                                 */
  SECURETIMER_CTRL3_TMR3CLR_CLEAR      = 1,     /*!< CLEAR : When written to a 1, the timer will automatically be
                                                     cleared to its reset state # (0 for count up counter, CMP0
                                                     for down counter)                                                         */
  SECURETIMER_CTRL3_TMR3CLR_DEFAULT    = 0,     /*!< DEFAULT : Default value set to 0. Timer works normally.                   */
} SECURETIMER_CTRL3_TMR3CLR_Enum;

/* ============================================  SECURETIMER CTRL3 TMR3EN [0..0]  ============================================ */
typedef enum {                                  /*!< SECURETIMER_CTRL3_TMR3EN                                                  */
  SECURETIMER_CTRL3_TMR3EN_DIS         = 0,     /*!< DIS : Counter/Timer 3 Disable.                                            */
  SECURETIMER_CTRL3_TMR3EN_EN          = 1,     /*!< EN : Counter/Timer 3 Enable.                                              */
} SECURETIMER_CTRL3_TMR3EN_Enum;

